// GEÇİCİ: sadece Vercel preview'da PDF okumayı doğrulamak için. main'e alınmadan silinecek.
import { NextResponse } from 'next/server'
import { extractCvText, cleanCvText } from '@/lib/cv-import'
const SAMPLE = ''
export async function GET() {
  if (process.env.VERCEL_ENV !== 'preview') return NextResponse.json({ error: 'not_found' }, { status: 404 })
  try {
    const text = cleanCvText(await extractCvText('cv.pdf', 'application/pdf', Buffer.from(SAMPLE, 'base64')))
    return NextResponse.json({ ok: true, chars: text.length, start: text.slice(0, 80) })
  } catch (e) {
    return NextResponse.json({ ok: false, error: String(e) }, { status: 500 })
  }
}
